import json,re,html
s=json.load(open('source.json'))[0]
p=s['source_xml'].replace(' align="center"','')
changes=[]
def replace(old,new):
 global p
 assert p.count(old)==1,(old,p.count(old))
 p=p.replace(old,new);changes.append((old,new))
replace("-d'élaborer le cadre stratégique patrimonial et le cadre stratégique d'utilité sociale commun mentionnés à l'article L. 423-1-1 du code de la construction et de l'habitation ;", "-à la demande des associés concernés, d'élaborer le cadre stratégique patrimonial et le cadre stratégique d'utilité sociale commun mentionnés à l'article L. 423-1-1 du code de la construction et de l'habitation ; leur élaboration et leur actualisation sont facultatives ;")
replace('-de définir la politique technique des associés ;', '-à la demande des associés concernés, de définir une politique technique commune facultative, sans dispense des règles techniques, de sécurité, de salubrité et d’accessibilité applicables ;')
replace("-de définir et mettre en œuvre une politique d'achat des biens et services, hors investissements immobiliers, nécessaires à l'exercice par les associés de leurs activités ;", "-à la demande des associés concernés, de définir et mettre en œuvre une politique d'achat des biens et services, hors investissements immobiliers, nécessaires à leurs activités ; la participation à cette politique commune est facultative ;")
replace('-de développer une unité identitaire des associés et de définir des moyens communs de communication, notamment par la création ou la licence de marques et de signes distinctifs ;', '-à la demande des associés concernés, de développer une identité commune et de définir des moyens communs de communication, notamment par la création ou la licence de marques et de signes distinctifs ; aucune identité ni aucun moyen commun de communication n’est imposé ;')
replace("Les prêts et avances consentis sont soumis au régime de déclaration mentionné aux articles L. 423-15 et L. 423-16 du code de la construction et de l'habitation ;", "Les prêts et avances autorisés par les articles L. 423-15 et L. 423-16 du code de la construction et de l'habitation et consentis dans ce cadre entre la société et ses associés ou entre ses associés sont dispensés de déclaration préalable aux ministres chargés du logement et de l'économie et du délai d'opposition prévus par ces articles. Les autres conditions de ces financements, notamment celles relatives aux bénéficiaires, aux ressources mobilisables et à la rémunération, ainsi que l'information de la Caisse de garantie du logement locatif social lorsqu'elle est requise, demeurent applicables. Aucune déclaration ni autorisation de remplacement n'est exigée ;")
replace("-de prendre les mesures nécessaires pour garantir la soutenabilité financière du groupe ainsi que de chacun des organismes qui le constituent, autres que les collectivités territoriales et leurs groupements en application de l'article L. 423-1-2 du code de la construction et de l'habitation ;", "-de prendre les mesures nécessaires pour garantir la soutenabilité financière du groupe ainsi que de chacun des organismes qui le constituent, autres que les collectivités territoriales et leurs groupements en application de l'article L. 423-1-2 du code de la construction et de l'habitation ; aucune cession ni fusion ne peut être imposée sur ce fondement ;")
replace("après y avoir été spécialement agréée dans les conditions fixées à l'article L. 422-5 du code de la construction et de l'habitation après accord de la ou des collectivités territoriales concernées ou, le cas échéant, de leurs groupements,", "sans agrément spécial supplémentaire ni accord préalable des collectivités territoriales concernées ou de leurs groupements, l'agrément initial prévu à l'article L. 422-5 du code de la construction et de l'habitation demeurant requis et les conditions de fond applicables à ces compétences demeurant exigées,")
replace("par courrier recommandé au conseil d'administration ou au directoire (2)", "par écrit, remis contre récépissé ou adressé par tout moyen permettant d'établir sa réception, au conseil d'administration ou au directoire (2)")
replace("par pli recommandé avec demande d'avis de réception", "par écrit, remis contre récépissé ou adressé par tout moyen permettant d'établir sa date de réception")
replace("par lettre recommandée adressée au président du conseil d'administration ou du directoire", "par écrit, remis contre récépissé ou adressé par tout moyen permettant d'établir sa date de réception, au président du conseil d'administration ou du directoire")
replace("par courrier recommandé avec demande d'avis de réception à la société", "par écrit, remis contre récépissé ou adressé par tout moyen permettant d'établir sa date de réception, à la société")
replace("sous réserve de l'approbation administrative donnée dans les conditions prévues à l'article R. 422-17 du même code et que l'attributaire s'engage à utiliser", "sans approbation administrative, sous réserve que l'attributaire s'engage à utiliser")
replace('Les statuts de la société sont transmis au ministre chargé du logement et au préfet du département du siège de la société après chaque modification.', "La modification des statuts ne donne lieu à aucune transmission systématique au ministre chargé du logement ni au préfet du département du siège de la société. Aucune déclaration de remplacement n'est exigée. Les obligations de publicité et les pouvoirs légaux de contrôle demeurent applicables.")
transition="<p>Les allègements des clauses 4, 6, 6.1, 7, 13 et 14 s’appliquent à compter de l’entrée en vigueur des dispositions portant la présente réforme, aux sociétés existantes comme nouvelles relevant du régime institué par la loi n° 2018-1021 du 23 novembre 2018. Les missions communes devenues facultatives ne sont plus imposées par les présents statuts ; les cadres existants restent utilisables, sans réfection obligatoire. Les plans stratégiques de patrimoine, conventions d’utilité sociale et engagements contractuels valablement formés conservent leur régime propre. Les demandes d’agrément spécial ou d’accord préalable désormais dispensées deviennent sans objet. Aucune déclaration préalable ni régularisation d’une déclaration non encore déposée ne peut être exigée pour les financements couverts par la dispense, même convenus auparavant ; les déclarations déjà déposées restent utilisables et les décisions d’opposition déjà prises ne sont pas annulées. Aucune information de la société de garantie supprimée par ailleurs n’est rétablie. Les décisions de cession ou de fusion forcée fondées sur le seul article L. 423-1-2 ne peuvent plus être exécutées, même devenues définitives, sans défaire les contrats conclus ni les transferts réalisés. Les nouveaux modes de notification s’appliquent aux écrits remis ou adressés à compter de cette entrée en vigueur, sans recommencer les délais déjà ouverts. La dispense d’approbation de la clause 13 concerne les affectations décidées à compter de cette entrée en vigueur, même dans une liquidation déjà ouverte ; les décisions antérieures gardent leur régime et leurs recours. Aucune transmission ni régularisation de transmission ne peut être demandée après cette entrée en vigueur sur le seul fondement de la clause 14, même pour une modification antérieure. Les créances antérieures, droits des tiers et recours sont préservés. Les sociétés demeurées sous le régime antérieur en application du troisième alinéa du V de l’article 81 de la loi n° 2018-1021 du 23 novembre 2018 conservent ce régime et ses avantages pour toutes leurs opérations éligibles, y compris futures.</p>"
p+=transition
out={k:s[k] for k in ['code_id','source_id','source_sha256','number']}
out.update(proposed_xml=p,status='rewrite_draft',change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=["Transmission systématique des statuts modifiés au ministre et au préfet, sans déclaration substitutive.","Exclusivité des envois recommandés pour opposition, exclusion, retrait et demande d’agrément de cession.","Caractère obligatoire des quatre missions communes, coordonné à la proposition de L423-1-2.","Déclaration ministérielle préalable et délai d’opposition des financements dans le champ dispensé par L423-1-2.","Agrément spécial et accord territorial préalable d’extension des compétences, en coordination avec L423-1-2.","Approbation administrative de l’affectation de l’actif, en coordination avec L422-11 et R422-17."],reason="Réforme de fond : retrait de la transmission systématique après chaque modification statutaire et ouverture de moyens probants alternatifs aux recommandés imposés. Coordinations nécessaires des allègements déjà proposés à L423-1-2 et R422-17, sans les compter une seconde fois. Le reste des quinze clauses et leurs quatre notes est conservé intégralement : capital, représentation, droits patrimoniaux, comptes et affectation sociale des fonds protègent associés, locataires et créanciers. Les cotisations financent les missions de la société ; ce ne sont pas des taxes supprimables ici sans modifier leur fondement législatif.",review_notes="Lecture intégrale de la source et de ses quatre notes ; source_notes_xml est vide, aucun tableau ni compagnon joint. R423-86 maintient la mise en conformité par la première assemblée générale extraordinaire ; les dispenses prennent effet selon la transition sans attendre un envoi de statuts. Les propositions de L423-1-2 et R422-17 du corpus sont des projets, pas le droit en vigueur : leur adoption coordonnée est indispensable. La suppression de la révision périodique décidée pour L422-3 et L422-3-2 n’est pas étendue implicitement aux sociétés de coordination : clause 15 et loi de 1947 restent à leur champ. Les agréments d’entrée et de cession protègent la composition du capital et le rachat garanti ; ils demeurent, ainsi que l’agrément initial HLM. La clause 6.1 contient déjà un blanc après « préavis de » ; aucun nombre n’est inventé et le préavis salarial de quinze jours ne le remplit pas. Anomalies préexistantes conservées et signalées : clause 7 mentionne « cessionnaire et acheteur potentiel » ; clause 8B renvoie au conseil d’administration pour la représentation territoriale ; le capital ouvert à certaines sociétés publiques jusqu’à 50 % doit être confronté au troisième alinéa de L423-1-2, dont la version fournie est plus restrictive. Ces divergences ne sont pas corrigées par retrait d’une faculté favorable. Loi de 1947 et code de commerce hors lot : vérifier leurs règles impératives de notification sans prétendre les avoir modifiées. Aucun impôt annuel n’est instauré par l’exercice comptable annuel ou par la clause de distribution ; fiscalité IS et exonérations restent régies par le CGI. Aucun chiffrage économique ou budgétaire n’est établi.",benefit_review="Sont conservés pour les situations futures éligibles : exemption de L443-14 pour les cessions d’aménagement, activités facultatives, délégation des souscriptions, dispense de dépôt/publication des variations de capital, retrait et remboursement des apports, cession libre entre associés, prix de rachat au moins égal à la cession refusée, agrément acquis à défaut de rachat, vote par correspondance, distribution permise avec ses limites et caractère facultatif de la clause 11 selon la note 4. Les garanties patrimoniales et fiscales du régime historique restent réservées ; aucune exonération n’est fermée par les allègements.")
r=json.load(open('reference-targets.json'));key=s['code_id']+'|'+s['source_id']
analyses=["L1234-1 concerne le préavis de licenciement salarié, avec quinze jours pour les nouveaux contrats dans le projet et maintien des anciennes règles. Le retrait d’un associé de la clause 6.1 n’est pas un licenciement : ni ancienneté salariale ni notification de rupture d’emploi ne s’y appliquent. Aucun renvoi à cet article n’est ajouté.","L1221-2 proposé interdit les nouveaux CDD et distingue durée de mission et durée de l’emploi. La mise en commun de moyens humains prévue à la clause 4 ne fixe aucun terme d’emploi et ne déroge pas au contrat unique. Les statuts et mandats sociaux ne sont pas des contrats de travail ; les anciens contrats gardent leurs transitions propres.","L1234-9 règle l’indemnité patronale de rupture, seuil d’un an au terme effectif préavis inclus, calcul de toute l’ancienneté à 0,20 mois par année et plafond de six mois dans le projet. Le remboursement des parts de la clause 6.3 n’est pas cette indemnité ; aucune ancienneté ou notification salariale ne le conditionne. Les droits des anciens salariés et indemnités spéciales ne sont pas affectés."]
out['reference_checks']=[dict(target_key=k,view_sha256=r['targets'][k]['view_sha256'],assessment=a) for k,a in zip(r['requirements'][key],analyses)]
def effect(kind,mid,desc,before,after,old,new):
 return dict(kind=kind,measure_id=mid,description=desc,before=before,after=after,unit='legal_duty',affected_population='Sociétés de coordination sous forme de société anonyme coopérative à capital variable et leurs associés.',conditions_and_transition='Selon la disposition transitoire finale : sociétés du régime de 2018, existantes et nouvelles ; droits antérieurs et régimes historiques préservés.',replacement_or_new_burdens='Aucun dépôt, registre ou agrément substitutif ; garanties et contrôles autonomes conservés.',source_quote=old,proposed_quote=new)
effects=[]
for idx,kind,mid,desc in [(0,'coordination','societes-coordination-missions-facultatives','Coordination des quatre missions communes devenues facultatives, une seule mesure.'),(4,'coordination','societes-coordination-financements-dispense','Dispense de déclaration préalable des financements déjà proposée dans L423-1-2.'),(5,'coordination','societes-coordination-fin-transferts-forces','Le renvoi à la soutenabilité ne peut rétablir cession ou fusion forcée.'),(6,'coordination','societes-coordination-extension-sans-agrement-special','Coordination de la dispense d’agrément spécial et d’accord territorial.'),(7,'compliance_cost_reduced','societes-coordination-notifications-support-libre','Une mesure regroupant les quatre formalités postales : opposition, exclusion, retrait et cession.'),(11,'coordination','hlm-affectation-actif-sans-approbation','Coordination de la suppression de l’approbation, affectation sociale maintenue.'),(12,'obligation_removed','societes-coordination-fin-envoi-statuts','Suppression des deux transmissions systématiques de chaque modification statutaire.')]:
 old,new=changes[idx]
 effects.append(effect(kind,mid,desc,old,new,old,new))
out['substantive_impact']=dict(version=1,classification='material_reduction',assessment='La comparaison avec la source entière montre le retrait des deux envois systématiques de statuts et de l’exclusivité postale de quatre démarches. Les allègements de missions, financements, extension de compétences et affectation de l’actif sont comptés uniquement comme coordinations. Aucune baisse fiscale n’est revendiquée.',scope_limitations='Gain financier non chiffré, alternatives électroniques éventuellement déjà admises non comptées comme gain supplémentaire. Les règles impératives hors corpus et les incohérences de capital signalées restent à coordonner ; aucune réduction nette de complexité de tous les codes n’est démontrée.',new_burdens_review='Aucune charge nouvelle identifiée : les écrits et preuves de réception existaient déjà, les nouveaux supports sont facultatifs, et aucune donnée, attestation, déclaration ou autorisation de remplacement n’est créée. La mise en conformité des statuts relève de R423-86 déjà applicable.',effects=effects)
json.dump([out],open('answer.json','w'),ensure_ascii=False,indent=2)
